frm.example:
# 1. Set a single field value:
frm.set_value("posting_date", frappe.datetime.nowdate());

# 2. Set multiple fields simultaneously with a dictionary:
frm.set_value({
    status: "Approved",
    approved_by: frappe.session.user,
    approval_date: frappe.datetime.nowdate()
});

frappe.ui.form.on("Customer", {
    customer_type(frm) {
        const is_company = frm.doc.customer_type === "Company";
        // Show or hide multiple tax and registration fields together:
        frm.toggle_display(["tax_id", "incorporation_date", "registered_address"], is_company);
    }
});

frappe.ui.form.on("Employee", {
    is_contract_worker(frm) {
        const is_contract = frm.doc.is_contract_worker === 1;
        // Make agency name mandatory only if contract worker:
        frm.toggle_reqd("contract_agency_name", is_contract);
    }
});

frappe.ui.form.on("Quotation", {
    refresh(frm) {
        if (!frm.is_new() && frm.doc.docstatus === 1) {
            // Add a button inside the 'Create' dropdown:
            frm.add_custom_button(__("Sales Order"), () => {
                frappe.model.open_mapped_doc({
                    method: "erpnext.selling.doctype.quotation.quotation.make_sales_order",
                    frm: frm
                });
            }, __("Create"));

            // Add a standalone highlighted primary button:
            const btn = frm.add_custom_button(__("Quick Approve"), () => {
                frm.call("approve_deal").then(() => frm.reload_doc());
            });
            btn.addClass("btn-primary");
        }
    }
});

frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        // 1. Static filter on parent Link field:
        frm.set_query("customer", function() {
            return {
                filters: {
                    "disabled": 0,
                    "customer_group": "Commercial"
                }
            };
        });

        // 2. Dynamic filter on Child Table Link field based on parent warehouse:
        frm.set_query("item_code", "items", function(doc, cdt, cdn) {
            return {
                filters: {
                    "is_sales_item": 1,
                    "default_warehouse": frm.doc.set_warehouse
                }
            };
        });
    }
});

const row = frm.add_child("items", {
    item_code: "ITEM-001",
    qty: 1,
    rate: 100
});
frm.refresh_field("items");

frm.call({
    method: "calculate_taxes",
    args: { tax_rate: 18 },
    freeze: true,
    callback(r) {
        frm.reload_doc();
    }
});

